('e0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000001', 'Python Developer', 'IT & Software', 'Full Time', 'Hybrid', 'Pune, Maharashtra', 500000, 850000, '1–3 years', 'Join our core backend engineering unit building high-throughput microservices in Python.', ARRAY['Architect scalable Python APIs', 'Optimize SQL schemas and queries', 'Maintain Docker containers'], ARRAY['1-3 years Python experience', 'Familiarity with FastAPI/Django', 'PostgreSQL knowledge'], ARRAY['Python', 'FastAPI', 'Django', 'PostgreSQL', 'Docker'], 'Active'),
('e0000000-0000-0000-0000-000000000003', 'b0000000-0000-0000-0000-000000000002', 'd0000000-0000-0000-0000-000000000002', 'Frontend Developer (React / Next.js)', 'IT & Software', 'Full Time', 'Remote', 'Bengaluru, Karnataka', 600000, 1000000, '1–3 years', 'ZenScale is seeking a passionate Frontend Developer to craft lightning-fast web applications with Next.js, TypeScript, and Tailwind CSS.', ARRAY['Develop accessible and responsive UI', 'Collaborate on Figma designs', 'Optimize web performance'], ARRAY['Proficiency with React and Next.js', 'Experience with Tailwind CSS', 'State management skills'], ARRAY['React', 'Next.js', 'TypeScript', 'Tailwind CSS', 'Redux'], 'Active'),
('e0000000-0000-0000-0000-000000000004', 'b0000000-0000-0000-0000-000000000003', 'd0000000-0000-0000-0000-000000000003', 'Data Analyst', 'Data Science', 'Full Time', 'On-site', 'Hyderabad, Telangana', 450000, 750000, '0–1 years', 'Analyze large-scale enterprise datasets and generate automated reporting dashboards.', ARRAY['Write complex SQL queries', 'Design interactive PowerBI dashboards', 'Identify customer trends'], ARRAY['Degree in BCA, Statistics, or CS', 'SQL proficiency', 'Python data visualization'], ARRAY['SQL', 'Python', 'PowerBI', 'Tableau', 'Pandas'], 'Active'),
('e0000000-0000-0000-0000-000000000005', 'b0000000-0000-0000-0000-000000000005', 'd0000000-0000-0000-0000-000000000005', 'UI/UX Designer', 'Design', 'Full Time', 'Hybrid', 'Pune, Maharashtra', 550000, 900000, '1–3 years', 'Create delightful, intuitive user journeys and high-fidelity interface systems for mobile apps and web platforms.', ARRAY['Conduct usability testing', 'Create wireframes and prototypes in Figma', 'Maintain design system tokens'], ARRAY['Product design portfolio', 'Figma proficiency', 'Understanding of responsive design'], ARRAY['Figma', 'UI Design', 'UX Research', 'Wireframing', 'Prototyping'], 'Active')
